/* app.js - the machinery: hub, chapter player, industry explorer.
 *
 * Nothing here computes a statistic. Every number on the page comes out of
 * window.STORY, which scripts/build_site_data.py writes from the processed ABS
 * CSVs. If a figure on screen looks wrong, fix the analysis and re-run the
 * builder; do not edit this file.
 */
(function () {
  'use strict';


  var global = window;
  var D = window.STORY;
  var V = window.VIZ;
  var CH = window.CHARTS;
  var C = CH.C;
  var chapters = window.CHAPTERS.build(D);
  var $ = function (s, r) { return (r || document).querySelector(s); };


  var byCode = {};

  D.divisions.forEach(function (d) { byCode[d.code] = d; });



  // ================================================================ tooltip
  var tipEl;
  function tipHost() {
    if (!tipEl) {
      tipEl = document.createElement('div');
      tipEl.className = 'tip';
      $('.p-chart').appendChild(tipEl);
    }
    return tipEl;
  }


  function rowHtml(label, value) {

    return '<div class="row"><span>' + label + '</span><b>' + value + '</b></div>';

  }



  function makeTipHandlers(host) {
    return function (d) {
      return {
        mouseenter: function (e) { show(d, e); },
        mousemove: function (e) { move(e); },
        mouseleave: function () { if (tipEl) tipEl.classList.remove('on'); }
      };
    };


    /* The tooltip has to fit the chart area, and on a phone that area can be
       barely 300px square. So the content is trimmed to what the box can hold
       before it is measured, and it is never allowed to be taller than the
       frame it lives in. */
    function show(d, e) {
      var r = host.getBoundingClientRect();
      var compact = r.height < 400 || r.width < 440;
      var t = tipHost();
      var html = '<b>' + (d.name || d.short) + '</b>';
      /* `_rows` is what the bar and line hover targets pass: an ordered list of
         [label, value] pairs specific to the chart form, so the tooltip is not
         forced to be a division-shaped card in every chapter. */
      if (d._rows) {
        d._rows.forEach(function (r) {
          if (r && r.length >= 2) html += rowHtml(r[0], r[1]);
        });
      } else {
        if (d.jobs != null) html += rowHtml('Jobs ' + D.meta.baseYear, V.fmt(d.jobs, 0) + 'k');
        if (d.wage != null) html += rowHtml('Average pay', V.money(d.wage, 1));
        if (d.jobsGrowth != null) html += rowHtml('Jobs, 18 yrs', V.signed(d.jobsGrowth, 1));
        if (!compact && d.wageGrowth != null) html += rowHtml('Real pay, 18 yrs', V.signed(d.wageGrowth, 1));
        if (!compact && d.ivaGrowth != null) html += rowHtml('Output, 18 yrs', V.signed(d.ivaGrowth, 1));
        if (!compact && d.blurb) {
          html += '<div style="margin-top:6px;color:var(--muted)">' + d.blurb + '</div>';
        }
      }
      t.innerHTML = html;
      t.style.maxWidth = Math.max(140, Math.min(250, r.width - 16)) + 'px';
      t.style.maxHeight = Math.max(60, r.height - 16) + 'px';
      t.classList.add('on');
      move(e);
    }


    /* Measure, prefer above the cursor, flip below when there is no room, and
       clamp on both axes. The old version assumed a fixed half width and pulled
       the box up by 120% of its own height, which put it outside the frame. */
    function move(e) {
      var r = host.getBoundingClientRect();
      var t = tipHost();
      var pad = 8;
      var x = e.clientX - r.left;
      var y = e.clientY - r.top;
      var tw = t.offsetWidth || 220;
      var th = t.offsetHeight || 90;
      var left = Math.max(pad, Math.min(r.width - tw - pad, x - tw / 2));
      var top = y - th - 14;
      if (top < pad) top = y + 22;
      top = Math.max(pad, Math.min(r.height - th - pad, top));
      t.style.left = left + 'px';
      t.style.top = top + 'px';
    }
  }


  // ================================================================ read aloud
  /* Browser speech synthesis, off until asked for. The narration is written to
     be read, so it needs very little massaging, but figures like "$172.4k" and
     "2006-07" are read as gibberish by every engine, so they are expanded into
     words before they are spoken. Nothing is downloaded: this is the voice
     already on the reader's device. */
  var SAY = {
    on: false,
    supported: typeof window.speechSynthesis !== 'undefined' &&
               typeof window.SpeechSynthesisUtterance !== 'undefined',
    voice: null,
    /* Recorded narration, rendered by scripts/build_narration.py. ONE voice,
       en-IE-Emily, chosen by the reader after listening to ten candidates; the
       picker went with them, because a control that offers one option is just
       clutter. The browser's own speechSynthesis stays underneath as the
       fallback, because what THAT sounds like depends entirely on which voices
       the reader's machine happens to have installed.

       One mp3 per beat. A previous version put every beat in one file and
       seeked to a mark, which breaks on any server that does not answer Range
       requests: `seekable` stays empty and every seek is clamped to 0, so each
       beat played the opening of chapter 01. */
    clips: window.NARRATION || null,
    audio: null
  };

  SAY.recorded = !!(SAY.clips && Object.keys(SAY.clips).length);
  SAY.available = SAY.recorded || SAY.supported;
  SAY.gen = 0;              // bumped per reading; stale callbacks check it


  /* The only surviving use of a device voice is the fallback when the
     recording cannot be loaded at all, so this picks the least-bad English one
     rather than ranking a menu. */
  function pickVoice() {
    if (!SAY.supported) return null;
    var en = (window.speechSynthesis.getVoices() || []).filter(function (v) {
      return /^en/i.test(v.lang || '');
    });
    return en.filter(function (v) { return /^en-au/i.test(v.lang || ''); })[0] ||
           en.filter(function (v) { return /^en-gb/i.test(v.lang || ''); })[0] ||
           en[0] || null;
  }


  function speakable(text) {
    return String(text)
      .replace(/\$([\d,.]+)k\b/g, '$1 thousand dollars')
      .replace(/\$([\d,.]+)/g, '$1 dollars')
      .replace(/\b(\d{4})-(\d{2})\b/g, '$1 to 20$2')
      .replace(/\b(is|was|are|were|rose|grew|added|fell)\s+\+([\d.]+)%/g, '$1 up $2 percent')
      .replace(/\+([\d.]+)%/g, '$1 percent')
      .replace(/[-\u2212]([\d.]+)%/g, 'down $1 percent')
      .replace(/([\d.]+)%/g, '$1 percent')
      .replace(/\bIVA\b/g, 'industry value added')
      .replace(/\bABS\b/g, 'A B S')
      .replace(/\s+/g, ' ')
      .trim();
  }
  /* Exported for scripts/build_narration.py, which captures narration.json
     from the running page: the recordings have to be made from the same text
     the synthetic voice would say, and re-implementing these rules in the
     capture snippet is how the two quietly drift apart. */
  global.SPEAKABLE = speakable;

  function stopSpeaking() {
    if (SAY.audio) {
      SAY.audio.onended = null;
      SAY.audio.pause();
    }
    if (SAY.supported) {
      try { window.speechSynthesis.cancel(); } catch (e) { /* nothing to cancel */ }
    }
    var b = $('.p-voice');
    if (b) b.classList.remove('speaking');
  }

  /* Play the recording for this beat. Returns false if there is none, or if the
     browser refuses to play it, and the caller then falls back to the synthetic
     voice. A refusal is real and worth handling: opened straight off the disk as
     file://, some browsers will not load media at all. */
  /* Play this beat's recording. `onended` is the exact end of the beat, which
     is what Auto steps on; there is nothing to seek and nothing to time. */
  function playClip(key, gen) {
    if (!SAY.recorded) return false;
    var clip = SAY.clips[key];
    if (!clip) return false;
    var b = $('.p-voice');
    if (!SAY.audio) {
      SAY.audio = new Audio();
      SAY.audio.preload = 'auto';
    }
    var a = SAY.audio;
    a.src = 'assets/audio/' + clip.file;

    var stop = function (natural) {
      a.pause();
      if (b) b.classList.remove('speaking');
      if (natural === true) beatDone(gen);
    };
    a.onplaying = function () { if (gen === SAY.gen && b) b.classList.add('speaking'); };
    a.onended = function () { if (gen === SAY.gen) stop(true); };
    a.onerror = function () {
      if (gen !== SAY.gen) return;
      // the file itself is unreachable: give up on recordings for this session
      if (b) b.classList.remove('speaking');
      SAY.recorded = false;
      say(SAY.lastText, gen);
    };

    var p = a.play();
    if (p && p['catch']) {
      /* 🚨 A rejection here must NEVER disable the recordings. Every one of them
         is transient and normal:

           AbortError      stepping to the next beat pauses this clip while its
                           own play() promise is still pending. This fires on
                           every single advance through the story.
           NotAllowedError the browser wants a user gesture first, which the
                           very next tap supplies.

         An earlier version treated anything but NotAllowedError as fatal, so
         the first time a reader pressed the arrow key the whole story dropped
         back to the synthetic voice and stayed there. A genuine failure, a
         missing or undecodable file, arrives on the element's `error` event
         instead, which is where the fallback belongs. */
      p['catch'](function () {
        if (b) b.classList.remove('speaking');
      });
    }
    return true;
  }

  /* Phrases, not sentences. A speech engine given a whole paragraph reads it at
     one unvarying pitch, which is most of what people hear as "robotic". Cutting
     at sentence ends helps; cutting long sentences at their commas and colons
     too gives the reading the pauses a person would actually take.

     Split only where a full stop is followed by a capital, so "$172.4k" and
     "2006-07" survive, and only break a sentence at a comma when it is long
     enough to need the air. */
  function phrases(text) {
    var out = [];
    var parts;
    try {
      parts = text.split(/(?<=[.?!])\s+(?=[A-Z"'])/);
    } catch (e) {
      parts = [text];                         // no lookbehind: read it in one go
    }
    parts.forEach(function (s) {
      s = s.trim();
      if (!s) return;
      if (s.length <= 95) { out.push(s); return; }
      var buf = '';
      s.split(/(?<=[,;:])\s+/).forEach(function (clause) {
        if ((buf + ' ' + clause).trim().length > 95 && buf) { out.push(buf.trim()); buf = clause; }
        else { buf = (buf ? buf + ' ' : '') + clause; }
      });
      if (buf.trim()) out.push(buf.trim());
    });
    return out.length ? out : [text];
  }

  function say(text, gen) {
    if (!SAY.on || !SAY.supported || !text) return;
    if (gen !== undefined && gen !== SAY.gen) return;
    stopSpeaking();
    if (!SAY.voice) SAY.voice = pickVoice();
    var b = $('.p-voice');
    var parts = phrases(speakable(text));
    var n = parts.length;
    parts.forEach(function (part, i) {
      var u = new SpeechSynthesisUtterance(part);
      if (SAY.voice) { u.voice = SAY.voice; u.lang = SAY.voice.lang; } else { u.lang = 'en-AU'; }
      /* Declination: real speech starts a little higher and drifts down across a
         passage, and slows into the last phrase. Holding one pitch for forty
         seconds is exactly what a machine sounds like. A question goes up at the
         end instead, which is the one place the contour reverses. */
      var through = n > 1 ? i / (n - 1) : 0;
      var ends = /\?$/.test(part);
      u.pitch = ends ? 1.10 : (1.06 - through * 0.12);
      u.rate = 0.95 - through * 0.05;
      u.volume = 1;
      if (i === 0) u.onstart = function () { if (b) b.classList.add('speaking'); };
      if (i === n - 1) u.onend = function () {
        if (b) b.classList.remove('speaking');
        beatDone(gen);
      };
      u.onerror = function () { if (b) b.classList.remove('speaking'); };
      if (gen !== undefined && gen !== SAY.gen) return;   // superseded mid-queue
      try { window.speechSynthesis.speak(u); } catch (e) { /* some engines refuse */ }
    });
  }


  /* The voice reads `say`, never the short on-screen line, and it does not
     announce the chapter: the number is already on screen and hearing
     "Chapter one" before every story was the first thing the reader asked to
     lose. */
  /* The reading of one beat has finished on its own. This is the ONLY place
     Auto advances from: a fixed timer would either cut the voice off or leave
     it hanging, which is exactly the complaint that produced this button. */
  function beatDone(gen) {
    if (gen !== undefined && gen !== SAY.gen) return;
    if (!P.auto || !P.open) return;
    clearTimeout(P.autoT);
    P.autoT = setTimeout(function () {
      if (P.auto && P.open && gen === SAY.gen) step(1);
    }, 900);
  }

  function setAuto(on) {
    P.auto = !!on;
    var b = $('.p-auto');
    if (b) b.setAttribute('aria-pressed', P.auto ? 'true' : 'false');
    try { localStorage.setItem('wtwi.auto', P.auto ? '1' : '0'); } catch (e) { /* private mode */ }
    clearTimeout(P.autoT);
    // Auto with the voice off is just a slideshow on a guessed timer; it turns
    // the narration on instead, and the reading is what paces it.
    if (P.auto && !SAY.on) setVoice(true);
  }

  function sayBeat(chapter, beat, index) {
    if (!SAY.on) return;
    SAY.lastText = beat.say || beat.text;
    var gen = ++SAY.gen;
    stopSpeaking();
    var key = chapter.id + '-' + index;
    if (playClip(key, gen)) return;
    say(SAY.lastText, gen);
  }


  function setVoice(on) {
    SAY.on = !!on;
    var b = $('.p-voice');
    if (b) b.setAttribute('aria-pressed', SAY.on ? 'true' : 'false');
    try { localStorage.setItem('wtwi.voice', SAY.on ? '1' : '0'); } catch (e) { /* private mode */ }
    if (!SAY.on) { stopSpeaking(); if (P.auto) setAuto(false); return; }
    if (P.open) sayBeat(chapters[P.ci], chapters[P.ci].beats[P.bi], P.bi);
  }


  // ================================================================ hero
  /* The opening bubble field, plus the card that opens when one is tapped. The
     card is deliberately the same four numbers the explorer leads with, so the
     two agree, and its button hands the reader straight to the full profile. */
  var heroView = null;

  /* Ranks across the eighteen visible industries, worked out once. A number on
     its own ("1,907k people") means nothing to a reader with no feel for the
     scale; "biggest of 18, one in seven of all the jobs here" does. */
  var RANK = (function () {
    var vis = D.divisions.filter(function (d) { return !d.hidden; });
    var totalJobs = vis.reduce(function (t, d) { return t + d.jobs; }, 0);
    var by = {};
    function rankOn(field) {
      vis.slice().sort(function (a, b) { return b[field] - a[field]; })
        .forEach(function (d, i) {
          (by[d.code] = by[d.code] || {})[field] = i + 1;
        });
    }
    ['jobs', 'wage', 'jobsGrowth', 'wageGrowth', 'jobs5y'].forEach(rankOn);
    return { of: vis.length, rank: by, totalJobs: totalJobs };
  })();

  function ord(n) {
    var t = n % 100;
    if (t >= 11 && t <= 13) return n + 'th';
    return n + ({ 1: 'st', 2: 'nd', 3: 'rd' }[n % 10] || 'th');
  }

  function rankWord(r, of) {
    if (r === 1) return 'highest of ' + of;
    if (r === of) return 'lowest of ' + of;
    return ord(r) + ' of ' + of;
  }

  function heroRow(label, value, meaning, tone) {
    return '<div class="hc-row"><div class="l">' + label + '</div>' +
      '<div class="v' + (tone ? ' ' + tone : '') + '">' + value + '</div>' +
      '<div class="m">' + meaning + '</div></div>';
  }

  function heroCard(code) {
    var card = $('#hero-card');
    var photos = $('#hero-photos');
    if (!code) { card.hidden = true; if (photos) photos.hidden = true; return; }
    var d = byCode[code];
    if (!d) { card.hidden = true; if (photos) photos.hidden = true; return; }
    var H = D.economy.headline;
    var rk = RANK.rank[code] || {};
    var of = RANK.of;
    var tone = function (v) { return v >= 0 ? 'pos' : 'neg'; };

    var payGap = d.wage - H.wageRealLast;
    var shareOfJobs = d.jobs / RANK.totalJobs * 100;

    var html =
      '<div class="hc-top"><span class="hc-ic" aria-hidden="true">' + d.icon + '</span>' +
      '<h3>' + d.short + '</h3>' +
      '<button class="hc-x" type="button" aria-label="Close">&times;</button></div>' +
      '<p class="hc-blurb">' + d.blurb + '</p><div class="hc-rows">';

    html += heroRow('People employed', V.fmt(d.jobs, 0) + 'k',
      '<span class="hc-rank">' + rankWord(rk.jobs, of) + '</span>' +
      shareOfJobs.toFixed(1) + '% of every job in this data');

    html += heroRow('Average pay', V.money(d.wage, 1),
      '<span class="hc-rank">' + rankWord(rk.wage, of) + '</span>' +
      (Math.abs(payGap) < 1
        ? 'right on the national average'
        : V.money(Math.abs(payGap), 1) + ' ' + (payGap > 0 ? 'above' : 'below') +
          ' the ' + V.money(H.wageRealLast, 1) + ' average'));

    html += heroRow('Jobs since ' + D.meta.firstYear, V.signed(d.jobsGrowth, 0),
      '<span class="hc-rank">' + rankWord(rk.jobsGrowth, of) + '</span>' +
      (d.jobsGrowth >= 0
        ? V.fmt(d.jobs - d.jobsFirst, 0) + 'k more people than in ' + D.meta.firstYear
        : V.fmt(d.jobsFirst - d.jobs, 0) + 'k fewer people than in ' + D.meta.firstYear),
      tone(d.jobsGrowth));

    html += heroRow('Pay since ' + D.meta.firstYear + ', after inflation',
      V.signed(d.wageGrowth, 0),
      '<span class="hc-rank">' + rankWord(rk.wageGrowth, of) + '</span>' +
      'the economy managed ' + V.signed(H.wageRealGrowth, 0) + ' over the same years',
      tone(d.wageGrowth));

    html += heroRow('Hiring, last five years', V.signed(d.jobs5y, 0),
      '<span class="hc-rank">' + rankWord(rk.jobs5y, of) + '</span>' +
      (d.jobs5y >= D.benchmarks.jobs5y ? 'faster' : 'slower') + ' than the national ' +
      V.signed(D.benchmarks.jobs5y, 0),
      tone(d.jobs5y));

    html += '</div><button class="hc-go" type="button">See the full profile &darr;</button>';
    card.innerHTML = html;
    card.hidden = false;
    card.scrollTop = 0;

    if (photos) {
      /* Three pictures of what work in that industry actually looks like, in a
         column beside the numbers. Uses whatever photos build_site_data exposed:
         the primary plus any extras, and pads with the primary if fewer than
         three exist so the column stays a column. */
      var pool = d.photos && d.photos.length ? d.photos.slice() : (d.photo ? [d.photo] : []);
      var labels = (d.photoLabels || []).slice();
      /* Show one photo per SUB-INDUSTRY, up to 3. If the division has only 2
         (or 1) sub-industries, only 2 (or 1) photos appear — no padding with
         duplicates, because two identical photos say less than one. */
      if (pool.length) {
        photos.innerHTML = pool.slice(0, 3).map(function (src, i) {
          var lb = labels[i] || d.short;
          return '<figure><img src="' + src + '" alt="">' +
            '<figcaption>' + d.short + (lb && lb !== d.short ? ' &middot; ' + lb : '') +
            '</figcaption></figure>';
        }).join('');
        photos.hidden = false;
      } else {
        photos.hidden = true;
      }
    }
    card.querySelector('.hc-x').addEventListener('click', function () {
      if (heroView) heroView.close();
    });
    card.querySelector('.hc-go').addEventListener('click', function () {
      openInExplorer(code);
    });
  }

  function openInExplorer(code) {
    EX.level = 'division';
    EX.sel = code;
    EX.q = '';
    var search = $('#exp-search');
    if (search) search.value = '';
    Array.prototype.forEach.call(document.querySelectorAll('[data-level]'), function (b) {
      b.setAttribute('aria-pressed', b.getAttribute('data-level') === 'division' ? 'true' : 'false');
    });
    renderExplorer();
    $('#explore').scrollIntoView({ behavior: V.reduceMotion ? 'auto' : 'smooth', block: 'start' });
    var row = document.querySelector('.exp-row[aria-selected="true"]');
    if (row) row.scrollIntoView({ block: 'nearest' });
  }

  function buildHero() {
    var stage = $('#hero-stage');
    if (!stage || !global.HERO) return;
    heroView = new global.HERO.Hero(stage, D, heroCard);
    // the key is generated from the ramp itself, so it can never drift from it
    var key = $('#lg-ramp');
    if (key) {
      key.innerHTML = global.HERO.RAMP.map(function (c) {
        return '<i style="background:' + c + '"></i>';
      }).join('');
    }
  }
  /* Which voices exist is entirely up to the reader's browser and operating
     system. Edge publishes a few hundred neural ones; a bare Windows install
     has three robotic SAPI voices and nothing else. So the site picks the best
     it can find and then gets out of the way: if there is more than one English
     voice, the reader can choose, and the choice is remembered. */
  // ================================================================ nav
  /* A hairline of progress and a bar that appears once the opening screen is
     behind you. The scroll listener is passive and writes a single custom
     property, so it never forces layout while the bubbles are drifting. */
  function navBar() {
    var sfx = $('.nav-sfx');
    if (sfx && window.SFX) {
      sfx.setAttribute('aria-pressed', window.SFX.enabled() ? 'true' : 'false');
      sfx.addEventListener('click', function () {
        var on = !window.SFX.enabled();
        window.SFX.set(on);
        sfx.setAttribute('aria-pressed', on ? 'true' : 'false');
        if (on) window.SFX.tap();
      });
    } else if (sfx) {
      sfx.hidden = true;
    }
    var nav = $('.nav');
    var prog = $('.nav-prog');
    if (!nav || !prog) return;
    var ticking = false;

    function paint() {
      ticking = false;
      var doc = document.documentElement;
      var max = doc.scrollHeight - doc.clientHeight;
      var y = window.scrollY || doc.scrollTop || 0;
      prog.style.setProperty('--p', (max > 0 ? (y / max) * 100 : 0).toFixed(2) + '%');
      nav.classList.toggle('on', y > doc.clientHeight * 0.6);
    }

    window.addEventListener('scroll', function () {
      if (!ticking) { ticking = true; requestAnimationFrame(paint); }
    }, { passive: true });
    paint();
  }

  // ================================================================ hub cards
  /* The last chapter is the one that answers the question the other nine only
     supply evidence for, so it does not sit in the grid with them: it gets the
     full width underneath, which is where a reader who skips everything else
     will still land on it. */
  function buildCards() {
    var grid = $('#cards');
    var fin = $('#finale');
    chapters.forEach(function (c, i) {
      // the last TWO are the closing pair: job types, then what to do about it
      var closing = i >= chapters.length - 2;
      var host = closing && fin ? fin : grid;
      var b = document.createElement('button');
      b.className = 'card rv';
      b.type = 'button';
      b.innerHTML =
        '<span class="num">' + c.num + '</span>' +
        '<span class="go" aria-hidden="true">&rarr;</span>' +
        '<h3>' + c.question + '</h3>' +
        '<p class="teaser">' + c.teaser + '</p>' +
        '<span class="who">' + c.persona + '</span>';
      b.addEventListener('click', function () { open(i, 0); });
      b.addEventListener('pointermove', function (e) {
        var r = b.getBoundingClientRect();
        b.style.setProperty('--mx', (e.clientX - r.left) + 'px');
        b.style.setProperty('--my', (e.clientY - r.top) + 'px');
      });
      host.appendChild(b);
    });
  }


  // ================================================================ player

  var P = {

    open: false, inited: false, ci: 0, bi: 0, scene: null, host: null,
    tip: null, chart: null, rt: 0

  };



  function open(ci, bi) {
    if (window.SFX && !P.open) window.SFX.open();
    P.ci = ci;
    P.bi = bi || 0;
    var el = $('.player');
    /* One-time setup is keyed off P.inited, NOT off P.open. Closing the player
       leaves the Scene in place, so tying construction to "not currently open"
       built a second <svg> inside .scene-host on every reopen, and the previous
       chapter's chart went on showing through underneath the new one. */
    if (!P.inited) {
      P.inited = true;
      P.host = $('.scene-host');
      P.scene = new V.Scene(P.host);
      P.chart = null;
      P.tip = makeTipHandlers($('.p-chart'));
      // The pane can change size without a window resize event (the layout
      // reflows when the player opens, and the desktop app can resize the pane
      // on its own), so watch the host itself rather than the window.
      if (window.ResizeObserver) {
        var ro = new ResizeObserver(function () {
          if (!P.open) return;
          clearTimeout(P.rt);
          P.rt = setTimeout(function () {
            if (P.scene.w !== P.host.clientWidth || P.scene.h !== P.host.clientHeight) {
              P.scene.measure();
              paint(true);
            }
          }, 120);
        });
        ro.observe(P.host);
      }
      /* 🚨 Clicking the picture does NOT advance. It used to, and it made the
         chart hostile: you cannot point at a bar, drag a scrollable panel or
         even click to focus the window without losing your place. Stepping is
         the arrows, the keyboard and the progress dots, all of which are
         deliberate. */
      dragScroll($('.p-chart'));
    }
    if (!P.open) {
      P.open = true;
      document.body.classList.add('locked');
      el.classList.add('on');
      el.setAttribute('aria-hidden', 'false');
    }
    var c = chapters[ci];
    $('.p-top .num').textContent = c.num;
    $('.p-top h2').textContent = c.question;
    // Chapters 03 and 04 are the same scatter asking two different questions.
    // Keeping the marks alive is the whole point: the eighteen dots slide to the
    // new axis instead of being wiped and redrawn. Only a genuine change of
    // chart form earns a clear.
    if (P.chart !== c.chart) { P.scene.clear(); }
    P.chart = c.chart;
    paint(true);
    if (location.hash !== '#' + c.id) history.replaceState(null, '', '#' + c.id);
  }


  function close() {
    if (!P.open) return;
    if (window.SFX) window.SFX.close();
    P.open = false;
    var el = $('.player');
    el.classList.remove('on');
    el.setAttribute('aria-hidden', 'true');
    document.body.classList.remove('locked');
    V.stopAll();
    clearTimeout(P.autoT);
    stopSpeaking();
    // leave nothing behind for the next chapter to show through
    if (P.scene) P.scene.clear();
    P.chart = null;
    if (tipEl) tipEl.classList.remove('on');
    history.replaceState(null, '', location.pathname + location.search + '#chapters');
  }


  function step(dir) {
    var c = chapters[P.ci];
    var n = P.bi + dir;
    if (n < 0) {
      if (P.ci === 0) return;
      P.ci--; open(P.ci, chapters[P.ci].beats.length - 1); return;
    }
    if (n >= c.beats.length) {
      if (P.ci >= chapters.length - 1) { close(); return; }
      open(P.ci + 1, 0); return;
    }
    P.bi = n;
    paint(false);
  }


  /* Grab-and-drag scrolling, for the chapters whose chart is taller than the
     pane. The wheel already works; this is for a trackpad-less mouse and for
     touch, and it is what the reader reaches for on a long list. A drag of a
     few pixels is still a click, so nothing below it is blocked. */
  function dragScroll(host) {
    var down = false, y0 = 0, t0 = 0, moved = false;
    host.addEventListener('pointerdown', function (e) {
      if (!host.classList.contains('scrolly')) return;
      if (e.target.closest('button')) return;
      down = true; moved = false;
      y0 = e.clientY; t0 = host.scrollTop;
      host.classList.add('grabbing');
    });
    host.addEventListener('pointermove', function (e) {
      if (!down) return;
      var dy = e.clientY - y0;
      if (Math.abs(dy) > 3) moved = true;
      host.scrollTop = t0 - dy;
    });
    ['pointerup', 'pointercancel', 'pointerleave'].forEach(function (ev) {
      host.addEventListener(ev, function () { down = false; host.classList.remove('grabbing'); });
    });
    host.addEventListener('click', function (e) { if (moved) e.stopPropagation(); }, true);
  }


  /* Cheap positive integer hash for the portrait shuffle. djb2. */
  function hashInt(str) {
    var h = 5381;
    for (var i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) | 0;
    return Math.abs(h);
  }

  /* A soft "no photograph more than 3 times" rule: pick the variant the hash
     points at first; if that one has already been shown 3 times this session,
     rotate to the next variant with fewer than 3 uses. Deterministic per beat
     within a session, so a reader who scrolls back sees the same picture. */
  var _picks = {};
  function pickPortrait(pool, seed) {
    var n = pool.length;
    var start = hashInt(seed) % n;
    for (var i = 0; i < n; i++) {
      var idx = (start + i) % n;
      var src = pool[idx];
      if ((_picks[src] || 0) < 3) { _picks[src] = (_picks[src] || 0) + 1; return { src: src, idx: idx }; }
    }
    /* Every variant is already at 3 uses — take the hash pick anyway. */
    var fallback = pool[start];
    _picks[fallback] = (_picks[fallback] || 0) + 1;
    return { src: fallback, idx: start };
  }

  /* Auto-detect which divisions a beat mentions by scanning its on-screen text
     with a plain case-insensitive substring test. Longest name first so
     "Health care and social assistance" is matched before "Health care". At
     most 3 codes, deduped. */
  var _lcNames = null;
  function _names() {
    if (_lcNames) return _lcNames;
    _lcNames = D.divisions.slice()
      .filter(function (d) { return !d.hidden; })
      .sort(function (a, b) { return b.short.length - a.short.length; })
      .map(function (d) { return { code: d.code, lc: d.short.toLowerCase() }; });
    return _lcNames;
  }
  function detectPortraits(text) {
    if (!text) return [];
    var lc = String(text).toLowerCase();
    var found = [];
    _names().forEach(function (n) {
      if (found.length >= 3) return;
      if (lc.indexOf(n.lc) >= 0 && found.indexOf(n.code) < 0) found.push(n.code);
    });
    return found;
  }

  function paint(first) {
    var c = chapters[P.ci];
    var beat = c.beats[P.bi];

    /* 🚨 FIRST, before the scene is measured. The strip is part of the
       player's layout, so putting it up afterwards shrinks the chart pane
       under a chart that has already been laid out, and the bottom row
       ends up below the frame.

       A beat that names one or more industries shows a PHOTOGRAPH of each,
       under the numbers. An industry is people and places before it is a
       figure, and two stat cards leave most of that column empty. The images
       are local files fetched and licence-checked by
       scripts/fetch_industry_photos.py, so the site still makes no network
       calls; the credits are rendered under the caveats. */
    var art = $('.p-art');
    if (art) {
      /* Codes come from THREE places, in order:
         1. `beat.portraits` / `beat.portrait` explicitly set in chapters.js
         2. Names in `beat.text` matched against every industry's `short`
         For each code we then pick a variant of that industry's photograph
         using a stable hash of (chapter, beat, code), so the same beat always
         shows the same photo (predictable), different beats vary the picture
         (shuffle), and each of the 3 variants gets roughly a third of the
         mentions (the "no photo more than 3 times" rule). */
      var codes = beat.portraits || (beat.portrait ? [beat.portrait] : []);
      if (!codes.length) codes = detectPortraits(beat.text);
      var seedKey = c.id + ':' + P.bi + ':';
      var pics = codes.map(function (code) {
        var d = byCode[code];
        if (!d) return null;
        var pool = (d.photos && d.photos.length) ? d.photos
                 : (d.photo ? [d.photo] : []);
        if (!pool.length) return null;
        var pick = pickPortrait(pool, seedKey + code);
        var labels = d.photoLabels || [];
        var label = labels[pick.idx] || labels[0] || d.short;
        return { short: d.short, photo: pick.src, label: label };
      }).filter(Boolean);
      if (pics.length) {
        art.className = 'p-art n' + Math.min(pics.length, 3);
        art.innerHTML = pics.map(function (d, i) {
          var cap = d.label && d.label !== d.short
            ? d.short + ' <span class="p-art-sub">' + d.label + '</span>'
            : d.short;
          return '<figure style="animation-delay:' + (i * 0.1).toFixed(2) + 's">' +
            '<img src="' + d.photo + '" alt="">' +
            '<figcaption>' + cap + '</figcaption></figure>';
        }).join('');
        art.hidden = false;
      } else {
        art.hidden = true;
        art.innerHTML = '';
      }
    }


    /* A chart taller than its pane. `scrollRows` is how many rows the builder
       is about to draw; the host gets an explicit height and .p-chart scrolls,
       so a reader can go and find their own job type instead of being shown
       the top eight. */
    var rows = (beat.state && beat.state.scrollRows) || 0;
    var pane = $('.p-chart');
    var wanted = rows ? Math.max(pane.clientHeight - 36, rows * 30 + 54) : 0;
    pane.classList.toggle('scrolly', !!rows);
    P.host.style.height = rows ? wanted + 'px' : '';
    if (rows) pane.scrollTop = 0;

    P.scene.measure();
    var ctx = {
      w: P.scene.w, h: P.scene.h, data: D,
      beat: beat.state || {},
      tipHandlers: P.tip
    };
    var marks = CH.builders[c.chart](ctx);
    P.scene.render(marks, {
      dur: first ? 850 : 700,
      stagger: first ? 14 : 0
    });
    // the sound belongs to the picture arriving, not to the key that asked for it
    if (window.SFX) window.SFX.reveal(c.chart);


    // narration
    $('.beat-n').textContent = 'Step ' + (P.bi + 1) + ' of ' + c.beats.length;
    var tx = $('.p-text');
    tx.style.opacity = 0;
    setTimeout(function () { tx.textContent = beat.text; tx.style.opacity = 1; }, first ? 0 : 130);
    tx.style.transition = 'opacity .28s';


    // stat cards
    var sh = $('.p-stats');
    sh.innerHTML = '';
    (beat.stats || []).forEach(function (s, i) {
      var d = document.createElement('div');
      d.className = 'stat' + (s.accent ? ' ' + s.accent : '');
      d.innerHTML = '<div class="l">' + s.label + '</div><div class="v">' + s.value + '</div>' +
        (s.note ? '<div class="n">' + s.note + '</div>' : '');
      d.style.opacity = 0;
      sh.appendChild(d);
      setTimeout(function () {
        d.style.transition = 'opacity .45s, transform .45s';
        d.style.opacity = 1;
      }, 220 + i * 110);
    });


    // the chapter's verdict, once the story has earned it
    var ans = $('.p-answer');
    if (beat.pivot) {
      $('.p-answer p').textContent = c.answer;
      ans.style.display = '';
    } else {
      ans.style.display = 'none';
    }


    // progress
    var segs = $('.segs');
    segs.innerHTML = '';
    c.beats.forEach(function (_, i) {
      var s = document.createElement('button');
      s.className = 'seg' + (i === P.bi ? ' now' : (i < P.bi ? ' done' : ''));
      s.type = 'button';
      s.setAttribute('aria-label', 'Step ' + (i + 1));
      s.addEventListener('click', function () { P.bi = i; paint(false); });
      segs.appendChild(s);
    });


    sayBeat(c, beat, P.bi);



    $('.p-prev').disabled = (P.ci === 0 && P.bi === 0);
    var last = P.bi === c.beats.length - 1;
    $('.p-next').setAttribute('aria-label',
      last ? (P.ci < chapters.length - 1 ? 'Next chapter' : 'Finish') : 'Next step');
    $('.p-hint').textContent = last
      ? (P.ci < chapters.length - 1 ? 'Next: ' + chapters[P.ci + 1].question : 'End of the story')
      : 'Click the chart or press the right arrow';
  }


  // ================================================================ explorer

  var EX = { level: 'division', sort: 'jobs', q: '', sel: null };



  function exRows() {
    var rows;
    if (EX.level === 'division') {
      rows = D.divisions.filter(function (d) { return !d.hidden; }).map(function (d) {
        return {
          code: d.code, name: d.short, full: d.name, sub: d.blurb, icon: d.icon,
          jobs: d.jobs, wage: d.wage, jobsGrowth: d.jobsGrowth,
          wageGrowth: d.wageGrowth, jobs5y: d.jobs5y, div: d
        };
      });
    } else {
      rows = D.subdivisions.map(function (s) {
        return {
          code: s.code, name: s.name, full: s.name, sub: s.divisionShort, icon: s.icon,
          jobs: s.jobs, wage: s.wage, jobsGrowth: s.jobsGrowth,
          wageGrowth: s.wageGrowth, jobs5y: s.jobs5y, subrec: s
        };
      });
    }
    if (EX.q) {
      var q = EX.q.toLowerCase();
      rows = rows.filter(function (r) {
        return (r.name + ' ' + r.sub).toLowerCase().indexOf(q) >= 0;
      });
    }
    rows.sort(function (a, b) { return b[EX.sort] - a[EX.sort]; });
    return rows;
  }


  function renderExplorer() {
    var rows = exRows();
    var list = $('#exp-list');
    list.innerHTML = '';
    if (!rows.length) {
      list.innerHTML = '<div style="padding:26px;color:var(--muted)">Nothing matches that search.</div>';
      return;
    }
    if (!EX.sel || !rows.some(function (r) { return r.code === EX.sel; })) EX.sel = rows[0].code;
    rows.forEach(function (r) {
      var b = document.createElement('button');
      b.type = 'button';
      b.className = 'exp-row';
      b.setAttribute('aria-selected', r.code === EX.sel ? 'true' : 'false');
      /* Every row has a thumbnail of its industry on the LEFT, in the gutter
         that used to be a slab of empty background. A job type inherits the
         photograph of the division it sits inside; the ABS gives Division K no
         photograph, so its rows fall back to the emoji icon so the column stays
         a column. */
      b.innerHTML =
        '<span class="nm">' + r.name + '<br><span class="sub">' + r.sub.split('.')[0] + '</span></span>' +
        '<span class="val">' + V.fmt(r.jobs, 0) + 'k</span>' +
        '<span class="val">' + V.money(r.wage, 0) + '</span>';
      b.addEventListener('click', function () {
        EX.sel = r.code;
        renderExplorer();
      });
      list.appendChild(b);
    });
    renderDetail(rows.filter(function (r) { return r.code === EX.sel; })[0]);
  }


  /* What the industry looks like from the inside, at the SAME level of detail
     as the panel above it: every job type gets the five figures and both
     sparklines, not just a bar. An industry average is made of job types that
     can pay three times each other (chapter 10), so a single row per job type
     was only half an answer. Picking a JOB TYPE shows the same list, its
     siblings, with it highlighted: the useful comparison is never against the
     whole economy, it is against the bench next to you. */
  /* Breakdown emits a flat list of grid cells for the outer subgrid:
     one .bd-head, then alternating (.bd-img, .bdc) pairs, one per sub-industry
     ranked by pay. The subgrid puts .bd-img in the left column (aligned with
     the industries list above it) and .bdc in the right column (aligned with
     the detail card above it). */
  function breakdown(r) {
    var code = r.div ? r.code : r.subrec.division;
    var kids = D.subdivisions.filter(function (x) { return x.division === code; });
    if (kids.length < 2) return '';
    var div = D.divisions.filter(function (x) { return x.code === code; })[0];
    var sorted = kids.slice().sort(function (a, b) { return b.wage - a.wage; });
    var hi = sorted[0].wage || 1;
    var cls = function (v) { return v >= 0 ? 'pos' : 'neg'; };

    var header =
      '<div class="bd-head">Inside ' + (div ? div.short : r.sub) + ': ' + kids.length +
        ' job types, by pay' +
        '<span class="sub">The industry average is ' + (div ? V.money(div.wage, 0) : '') +
          '. Inside it the pay runs from ' + V.money(sorted[sorted.length - 1].wage, 0) +
          ' to ' + V.money(sorted[0].wage, 0) + '.</span>' +
      '</div>';

    var body = sorted.map(function (x) {
      var me = !r.div && x.code === r.code;
      var short = shortJob(x.name);
      var img = x.photo
        ? '<div class="bd-img" style="background-image:url(\'' + x.photo + '\')">' +
            '<span class="cap">' + short + '</span>' +
          '</div>'
        : '<div class="bd-img"><span class="cap">' + short + '</span></div>';
      var desc = x.description ? '<p class="bdc-blurb">' + x.description + '</p>' : '';
      var card = '<div class="bdc' + (me ? ' me' : '') + '">' +
        '<div class="bdc-h">' +
          '<span class="bdc-n">' + x.icon + ' ' + short +
            (me ? ' <b>you are here</b>' : '') + '</span>' +
          '<span class="bdc-w">' + V.money(x.wage, 0) + '</span>' +
        '</div>' +
        desc +
        '<div class="bdc-bar"><i style="width:' + (x.wage / hi * 100).toFixed(1) + '%"></i></div>' +
        '<div class="kpis bdc-k">' +
          '<div class="kpi"><div class="l">Jobs</div><div class="v">' + V.fmt(x.jobs, 0) + 'k</div></div>' +
          '<div class="kpi"><div class="l">Pay</div><div class="v">' + V.money(x.wage, 0) + '</div></div>' +
          '<div class="kpi"><div class="l">Jobs, 18 yrs</div><div class="v ' + cls(x.jobsGrowth) + '">' + V.signed(x.jobsGrowth, 0) + '</div></div>' +
          '<div class="kpi"><div class="l">Real pay, 18 yrs</div><div class="v ' + cls(x.wageGrowth) + '">' + V.signed(x.wageGrowth, 0) + '</div></div>' +
          '<div class="kpi"><div class="l">Jobs, last 5 yrs</div><div class="v ' + cls(x.jobs5y) + '">' + V.signed(x.jobs5y, 0) + '</div></div>' +
        '</div>' +
        verdictHtml({ wage: x.wage, jobs5y: x.jobs5y }) +
        '<div class="bdc-s">' +
          spark(x.series.jobs, 'Employment, thousands', C.blue) +
          spark(x.series.wage, 'Pay, ' + D.meta.baseYear + ' dollars', C.orange) +
        '</div>' +
      '</div>';
      return img + card;
    }).join('');

    return header + body;
  }

  // ABS names a job type for a filing cabinet; this makes it a name again
  function shortJob(n) {
    return String(n)
      .replace(/\s*\(.*?\)\s*/g, ' ')
      .replace(/and related services/i, '')
      .replace(/services/i, '')
      .replace(/\s+/g, ' ')
      .trim();
  }


  function spark(vals, label, colour) {
    var w = 520, h = 92;
    var sp = CH.sparkPath(vals, w, h, 10);
    return '<div class="spark-box"><div class="cap"><span>' + label + '</span>' +
      '<span>' + D.meta.firstYear + ' to ' + D.meta.baseYear + '</span></div>' +
      '<svg viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none">' +
      '<path d="' + sp.d + '" fill="none" stroke="' + colour + '" stroke-width="2.5" ' +
      'stroke-linecap="round" stroke-linejoin="round" vector-effect="non-scaling-stroke"/>' +
      '<circle cx="' + sp.pts[sp.pts.length - 1][0].toFixed(1) + '" cy="' +
      sp.pts[sp.pts.length - 1][1].toFixed(1) + '" r="4" fill="' + colour + '"/>' +
      '</svg></div>';
  }


  /* Returns { label, tone, text } for the verdict card. The tone drives its
     colour (aqua = worth aiming at, blue = qualifier-heavy, orange = stepping
     stone, red = think twice). Text is 2-3 sentences of advice: whether to
     pick it, why, and what a qualification does for you here. */
  function verdictFor(r) {
    var bw = D.benchmarks.wage, bj = D.benchmarks.jobs5y;
    var paysWell = r.wage >= bw;
    var hiring = r.jobs5y >= bj;
    var shrinking = r.div && r.div.driver === 'Shrinking';
    var out;
    if (paysWell && hiring) {
      out = {
        tone: 'aqua', label: 'Worth aiming at',
        text: 'Pay is above the ' + V.money(bw, 0) + ' national average <b>and</b> hiring is above average — the rarest combination in this data. If you already hold a matching qualification, this is where it earns the most; if you do not, the entry paths are narrow and worth planning for.'
      };
    } else if (paysWell) {
      out = {
        tone: 'blue', label: 'Good pay, tight door',
        text: 'Pay is above the ' + V.money(bw, 0) + ' national average, but hiring has been slower than the economy as a whole. This is a target that rewards a specific qualification — a matching degree, trade certificate or licence turns a rare vacancy into an offer.'
      };
    } else if (hiring) {
      out = {
        tone: 'orange', label: 'Easy door, low ceiling',
        text: 'Hiring is above the ' + V.signed(bj, 0) + ' five-year average but pay sits below the ' + V.money(bw, 0) + ' national average. Fair as a first step, and worth using as one; the higher-paid job types inside it are the ones to qualify into and move across to.'
      };
    } else {
      out = {
        tone: 'red', label: 'Think twice',
        text: 'Both pay and hiring sit below the national average, so this is not a broad recommendation. Some specific job types inside it do far better than the industry average — check the breakdown below before ruling it in or out.'
      };
    }
    if (shrinking) {
      out.text += ' Real value added has fallen over eighteen years, so plan on the specific job type staying viable rather than the industry lifting you.';
    }
    return out;
  }
  function verdictHtml(r) {
    var v = verdictFor(r);
    return '<div class="verdict v-' + v.tone + '" data-verdict-label="' + v.label + '">' + v.text + '</div>';
  }


  function renderDetail(r) {
    if (!r) return;
    var host = $('#exp-detail');
    var series = r.div ? D.series[r.code] : r.subrec.series;
    var jobsVals = series.jobs, wageVals = r.div ? series.wage : r.subrec.series.wage;
    var cls = function (v) { return v >= 0 ? 'pos' : 'neg'; };
    var desc = r.div ? (r.div.description || r.div.blurb || '')
                     : (r.subrec && r.subrec.description) || '';
    host.innerHTML =
      '<h3>' + r.full + '</h3>' +
      '<div class="kind">' + (r.div ? 'Industry division' : 'Job type inside ' + r.sub) + '</div>' +
      (desc ? '<p class="blurb">' + desc + '</p>' : '') +
      '<div class="kpis">' +
      '<div class="kpi"><div class="l">Jobs, ' + D.meta.baseYear + '</div><div class="v">' + V.fmt(r.jobs, 0) + 'k</div></div>' +
      '<div class="kpi"><div class="l">Average pay</div><div class="v">' + V.money(r.wage, 0) + '</div></div>' +
      '<div class="kpi"><div class="l">Jobs, 18 yrs</div><div class="v ' + cls(r.jobsGrowth) + '">' + V.signed(r.jobsGrowth, 0) + '</div></div>' +
      '<div class="kpi"><div class="l">Real pay, 18 yrs</div><div class="v ' + cls(r.wageGrowth) + '">' + V.signed(r.wageGrowth, 0) + '</div></div>' +
      '<div class="kpi"><div class="l">Jobs, last 5 yrs</div><div class="v ' + cls(r.jobs5y) + '">' + V.signed(r.jobs5y, 0) + '</div></div>' +
      '</div>' +
      verdictHtml(r) +
      spark(jobsVals, 'Employment, thousands of people', C.blue) +
      spark(wageVals, 'Average pay per worker, in ' + D.meta.baseYear + ' dollars', C.orange) +
      '<div><span class="tag">' + (r.div ? r.div.quadrant : r.sub) + '</span>' +
      '<span class="tag">' + V.fmt(r.jobs, 0) + 'k people</span></div>';

    /* The breakdown goes BELOW the two columns, at the full width of the page.
       Inside the right-hand column it was a 500px trench: fifteen cards in a
       single narrow stack, each one mostly empty on both sides. */
    var bdHost = $('#exp-breakdown');
    if (bdHost) bdHost.innerHTML = breakdown(r);


    // draw the two sparklines on, left to right
    var sparkHosts = [host].concat(bdHost ? [bdHost] : []);
    var paths = [];
    sparkHosts.forEach(function (h) {
      paths = paths.concat(Array.prototype.slice.call(h.querySelectorAll('.spark-box path')));
    });
    paths.forEach(function (p, i) {
      var len = p.getTotalLength();
      p.setAttribute('stroke-dasharray', len);
      p.setAttribute('stroke-dashoffset', len);
      V.tween({
        dur: 900, delay: Math.min(i, 6) * 110, ease: V.ease.out,
        step: function (t) { p.setAttribute('stroke-dashoffset', len * (1 - t)); }
      });
    });
  }


  // ================================================================ reveal
  function reveals() {
    if (!('IntersectionObserver' in window)) {
      Array.prototype.forEach.call(document.querySelectorAll('.rv'), function (n) { n.classList.add('in'); });
      return;
    }
    var io = new IntersectionObserver(function (ents) {
      ents.forEach(function (e) {
        if (!e.isIntersecting) return;
        var n = e.target;
        var sibs = Array.prototype.indexOf.call(n.parentNode.children, n);
        setTimeout(function () { n.classList.add('in'); }, Math.min(sibs, 8) * 55);
        io.unobserve(n);
      });
    }, { rootMargin: '0px 0px -12% 0px' });
    Array.prototype.forEach.call(document.querySelectorAll('.rv'), function (n) { io.observe(n); });
  }


  // ================================================================ boot
  function boot() {
    // meta figures dotted through the prose
    Array.prototype.forEach.call(document.querySelectorAll('[data-fig]'), function (n) {
      var path = n.getAttribute('data-fig').split('.');
      var v = D;
      path.forEach(function (k) { v = v == null ? v : v[k]; });
      var f = n.getAttribute('data-fmt');
      n.textContent = f === 'pct' ? V.signed(v, 1)
        : f === 'money' ? V.money(v, 1)
        : f === 'num' ? V.fmt(v, 0)
        : String(v);
    });


    /* Every photograph is someone's work under a licence that requires the
       credit. Generated from the same data the images come from, so a new
       photo cannot ship uncredited. */
    var cr = $('#credits');
    if (cr) cr.textContent = 'Illustrative photographs of each ABS sub-industry, supplied by the project team.';

    buildHero();
    navBar();

    buildCards();

    renderExplorer();

    reveals();



    if (SAY.available) {
      var vb = $('.p-voice');
      vb.hidden = false;
      var ab = $('.p-auto');
      if (ab) {
        ab.hidden = false;
        var savedAuto = null;
        try { savedAuto = localStorage.getItem('wtwi.auto'); } catch (e) { savedAuto = null; }
        P.auto = savedAuto === '1';
        ab.setAttribute('aria-pressed', P.auto ? 'true' : 'false');
        ab.addEventListener('click', function () { setAuto(!P.auto); });
      }
      // Voices arrive asynchronously in most browsers.
      if (SAY.supported && window.speechSynthesis.getVoices().length === 0) {
        window.speechSynthesis.onvoiceschanged = function () { SAY.voice = pickVoice(); };
      }
      var saved = null;
      try { saved = localStorage.getItem('wtwi.voice'); } catch (e) { saved = null; }
      if (saved === '1') vb.setAttribute('aria-pressed', 'true');
      SAY.on = saved === '1';
      vb.addEventListener('click', function () { setVoice(!SAY.on); });
      window.addEventListener('beforeunload', stopSpeaking);
    }


    /* Anywhere outside the card and outside a circle closes it. The field
       handles its own empty space; this covers the rest of the page. */
    document.addEventListener('click', function (e) {
      if (!heroView || !heroView.selected) return;
      if (e.target.closest('.bub') || e.target.closest('#hero-card')) return;
      heroView.close();
    });
    document.addEventListener('keydown', function (e) {
      if (e.key === 'Escape' && !P.open && heroView && heroView.selected) heroView.close();
    });

    $('.p-close').addEventListener('click', close);

    $('.p-prev').addEventListener('click', function () { step(-1); });

    $('.p-next').addEventListener('click', function () { step(1); });



    $('#exp-search').addEventListener('input', function (e) {
      EX.q = e.target.value; renderExplorer();
    });
    Array.prototype.forEach.call(document.querySelectorAll('[data-level]'), function (b) {
      b.addEventListener('click', function () {
        EX.level = b.getAttribute('data-level');
        EX.sel = null;
        Array.prototype.forEach.call(document.querySelectorAll('[data-level]'), function (o) {
          o.setAttribute('aria-pressed', o === b ? 'true' : 'false');
        });
        renderExplorer();
      });
    });
    Array.prototype.forEach.call(document.querySelectorAll('[data-sort]'), function (b) {
      b.addEventListener('click', function () {
        EX.sort = b.getAttribute('data-sort');
        Array.prototype.forEach.call(document.querySelectorAll('[data-sort]'), function (o) {
          o.setAttribute('aria-pressed', o === b ? 'true' : 'false');
        });
        renderExplorer();
      });
    });


    document.addEventListener('keydown', function (e) {
      if (!P.open) return;
      if (e.key === 'Escape') { close(); }
      else if (e.key === 'ArrowRight' || e.key === ' ' || e.key === 'PageDown') { e.preventDefault(); step(1); }
      else if (e.key === 'ArrowLeft' || e.key === 'PageUp') { e.preventDefault(); step(-1); }
    });


    if (!window.ResizeObserver) {
      var rt;
      window.addEventListener('resize', function () {
        clearTimeout(rt);
        rt = setTimeout(function () { if (P.open) { P.scene.measure(); paint(true); } }, 160);
      });
    }


    // deep link straight into a chapter

    var h = location.hash.replace('#', '');

    chapters.forEach(function (c, i) { if (c.id === h) open(i, 0); });

  }



  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
